/* typo-tolerant word match */
function lev(a,b){if(Math.abs(a.length-b.length)>2)return 9;const d=[...Array(b.length+1).keys()];for(let i=1;i<=a.length;i++){let p=d[0];d[0]=i;for(let j=1;j<=b.length;j++){const t=d[j];d[j]=Math.min(d[j]+1,d[j-1]+1,p+(a[i-1]===b[j-1]?0:1));p=t}}return d[b.length]}
const fuzzy=(t,k)=>{if(k.includes(' ')||k.length<5||/[^\x00-\x7f]/.test(k))return false;const lim=k.length>=8?2:1;return t.trim().split(' ').some(w=>w.length>=4&&lev(w,k)<=lim)};
function norm(s){return ' '+String(s).toLowerCase().replace(/[^\p{L}\p{N}₹\s-]/gu,' ').replace(/\s+/g,' ').trim()+' '}
function answer(q,force){const lang=force||langOf(q);q=CHIPMAP[q]||q;const t=norm(q);let best=null,bs=0;
  for(const it of KB){let s=0;for(const k of it.k){const kk=norm(k);if(t.includes(kk)){s+=kk.trim().split(' ').length*2+ (kk.length>6?1:0)}else if(kk.trim().length>4&&t.includes(kk.trim().slice(0,-1)))s+=1;else if(fuzzy(t,kk.trim()))s+=1.5}s*=it.w||1;if(s>bs){bs=s;best=it}}
  if((!best||bs<1.2)&&(lang==='hl'||lang==='gl'))return {miss:1,a:lang==='gl'?`Maaf karjo, aa hu haji samjyo nathi. 🤔 Nondhani, fee, spardha ke sampark vishe puchho.${go('#/contact/us','AFAGS sampark')}`:`Sorry yaar, ye abhi samajh nahi aaya. 🤔 Registration, fees, events ya contact ke baare mein poochho.${go('#/contact/us','AFAGS contact')}`,c:lang==='gl'?['Nondhani kevi rite?','Fee ketli?','Aagami spardha','Sampark']:['Registration kaise kare?','Fees kitni hai?','Next event kab hai?','Contact']};
  if((!best||bs<1.2)&&lang!=='en')return {miss:1,a:lang==='gu'?`માફ કરશો, હું હજી આ સમજી શક્યો નથી. 🤔 નોંધણી, ફી, સ્પર્ધા કે સંપર્ક વિશે પૂછો.${go('#/contact/us','AFAGS સંપર્ક')}`:`माफ़ कीजिए, मैं अभी यह नहीं समझ पाया। 🤔 पंजीकरण, शुल्क, प्रतियोगिता या संपर्क के बारे में पूछिए।${go('#/contact/us','AFAGS संपर्क')}`,c:lang==='gu'?['નોંધણી કેવી રીતે?','ફી કેટલી?','આગામી સ્પર્ધા','સંપર્ક']:['पंजीकरण कैसे?','फीस कितनी?','अगली प्रतियोगिता','संपर्क']};
  if(!best||bs<1.2)return {miss:1,a:`I'm not sure about that yet. 🤔 Try one of these, search the site, or contact the AFAGS office.<br><button type="button" class="pc-l" data-act="search">Search the website ›</button>${go('#/contact/us','Contact AFAGS')}`,c:['How do I register?','Registration fee','Next event','Contact AFAGS']};
  const la=lang!=='en'&&LA[best.id]&&LA[best.id][lang];if(la)return {id:best.id,a:la(t),c:LA[best.id]['c'+lang]||(lang==='hl'?['Registration kaise kare?','Fees kitni hai?','Next event kab hai?','Contact']:lang==='gl'?['Nondhani kevi rite?','Fee ketli?','Aagami spardha','Sampark']:null)||(lang==='gu'?['નોંધણી કેવી રીતે?','ફી કેટલી?','આગામી સ્પર્ધા','સંપર્ક']:['पंजीकरण कैसे?','फीस कितनी?','अगली प्रतियोगिता','संपर्क'])};
  return {id:best.id,a:typeof best.a==='function'?best.a(t):best.a,c:best.c}}

