const timeGreet=L=>{const h=new Date().getHours();return h<5?T(L,{en:'Burning the midnight oil? 🌙',hi:'देर रात तक जाग रहे हो? 🌙',gu:'મોડી રાત સુધી જાગો છો? 🌙',hl:'Raat ke ullu ho kya? 🌙😄',gl:'Raat na ullu chho ke? 🌙😄'}):h<12?T(L,{en:'Good morning! ☀️',hi:'सुप्रभात! ☀️',gu:'સુપ્રભાત! ☀️',hl:'Good morning! ☀️',gl:'Good morning! ☀️'}):h<17?T(L,{en:'Good afternoon! 🌤️',hi:'नमस्ते! 🌤️',gu:'નમસ્તે! 🌤️',hl:'Namaste! 🌤️',gl:'Kem cho! 🌤️'}):T(L,{en:'Good evening! 🌆',hi:'शुभ संध्या! 🌆',gu:'શુભ સાંજ! 🌆',hl:'Good evening! 🌆',gl:'Good evening! 🌆'})};

/* small talk + fun intents (answered instantly, offline) */
function local2(q,L){const t=q.toLowerCase();let m;
  if((m=/(?:my name is|call me|mera naam|maru naam|mara naam|मेरा नाम|મારું નામ)\s+([\p{L}]{2,20})/u.exec(q))){ST.name=m[1][0].toUpperCase()+m[1].slice(1);saveST();
    return {mood:'happy',a:T(L,{en:`Nice to meet you, <b>${esc(ST.name)}</b>! 🤝 I'll remember that.`,hi:`आपसे मिलकर खुशी हुई, <b>${esc(ST.name)}</b>! 🤝`,gu:`તમને મળીને આનંદ થયો, <b>${esc(ST.name)}</b>! 🤝`,hl:`Milke achha laga, <b>${esc(ST.name)}</b>! 🤝 Yaad rakhunga.`,gl:`Malīne aanand thayo, <b>${esc(ST.name)}</b>! 🤝`}),c:chipsFor(L)}}
  if(/\b(joke|jokes|funny|make me laugh|hasao|hasa do|chutkula|majak|mazak|jok)\b|चुटकुला|जोक|જોક|ટુચકો/i.test(q))return {mood:'funny',a:pick(JOKES[L]||JOKES[{hl:'hi',gl:'gu'}[L]]||JOKES.en),c:[T(L,{en:'Another joke 😂',hi:'एक और 😂',gu:'બીજો જોક 😂',hl:'Ek aur joke 😂',gl:'Biju joke 😂'}),T(L,{en:'Fun fact 💡',hi:'रोचक तथ्य 💡',gu:'રસપ્રદ તથ્ય 💡',hl:'Fun fact 💡',gl:'Fun fact 💡'}),'Quiz 🧠']};
  if(/\b(fact|facts|did you know|trivia|interesting)\b|तथ्य|જાણો છો|તથ્ય/i.test(q))return {mood:'excited',a:'💡 '+pick(FACTS[L]||FACTS[{gl:'gu'}[L]]||FACTS.en),c:[T(L,{en:'Another fact 💡',hi:'एक और तथ्य 💡',gu:'બીજું તથ્ય 💡',hl:'Ek aur fact 💡',gl:'Biju fact 💡'}),'Quiz 🧠',T(L,{en:'Tell me a joke 😂',hi:'जोक सुनाओ 😂',gu:'જોક કહો 😂',hl:'Ek joke sunao 😂',gl:'Joke kaho 😂'})]};
  if(/\b(motivat|inspire|inspiration|quote|hausla|himmat|josh)\b|प्रेरणा|हिम्मत|પ્રેરણા|હિંમત/i.test(q))return {mood:'proud',a:'🔥 '+pick(MOTIV[L]||MOTIV[{gl:'gu'}[L]]||MOTIV.en),c:[T(L,{en:'One more 🔥',hi:'एक और 🔥',gu:'એક વધુ 🔥',hl:'Ek aur 🔥',gl:'Ek vadhu 🔥'}),'Quiz 🧠']};
  if(/^\s*(quiz|quiz 🧠|test me|play quiz|quiz khelo|quiz ramo)\b/i.test(t)||/क्विज़|ક્વિઝ/.test(q))return startQuiz(L);
  if(/\b(play|game|khel|khelo|ramiye|ramvu|bored|boring|bore)\b|खेल|રમ/i.test(q))return {mood:'excited',a:T(L,{en:`🎮 Let's play <b>Riposte!</b> Pick your move — ⚔️ Attack beats 🌀 Feint, 🛡️ Parry beats ⚔️ Attack, 🌀 Feint fools 🛡️ Parry. First to 5 touches wins!`,hi:`🎮 चलो <b>Riposte!</b> खेलें — ⚔️ अटैक 🌀 फ़ेंट को हराता है, 🛡️ पैरी ⚔️ अटैक को, 🌀 फ़ेंट 🛡️ पैरी को। पहले 5 टच जीतो!`,gu:`🎮 ચાલો <b>Riposte!</b> રમીએ — ⚔️ અટેક 🌀 ફેન્ટને હરાવે, 🛡️ પેરી ⚔️ અટેકને, 🌀 ફેન્ટ 🛡️ પેરીને. પહેલાં 5 ટચ જીતો!`,hl:`🎮 Chalo <b>Riposte!</b> khelte hain — ⚔️ Attack 🌀 Feint ko harata hai, 🛡️ Parry ⚔️ Attack ko, 🌀 Feint 🛡️ Parry ko. Pehle 5 touch jeeto!`,gl:`🎮 Chalo <b>Riposte!</b> ramiye — ⚔️ Attack 🌀 Feint ne harave, 🛡️ Parry ⚔️ Attack ne, 🌀 Feint 🛡️ Parry ne. Pehla 5 touch jeeto!`})+gameButtons(),c:[]};
  if(/\b(how are you|how r u|how are u|kaise ho|kaisa hai|kem cho|kem chho|majama|sab badhiya|what'?s up|wassup|sup)\b|कैसे हो|કેમ છો/i.test(q))return {mood:'happy',a:T(L,{en:`I'm sharp as a sabre and ready to help! ⚡😄 How about you${ST.name?', '+esc(ST.name):''}?`,hi:`मैं एकदम तलवार की धार जैसा तेज़ हूँ! ⚡😄 आप कैसे हो?`,gu:`હું તલવારની ધાર જેવો તેજ છું! ⚡😄 તમે કેમ છો?`,hl:`Ekdum mast, sabre ki tarah sharp! ⚡😄 Tum batao${ST.name?' '+esc(ST.name):''}?`,gl:`Ekdam majama, sabre jevo sharp! ⚡😄 Tame kem chho?`}),c:chipsFor(L)};
  if(/\b(who made you|who created you|who built you|kisne banaya|kone banavyo|your creator)\b|किसने बनाया|કોણે બનાવ્યો/i.test(q))return {mood:'proud',a:T(L,{en:'I was built for <b>AFAGS</b> to help fencers, parents and coaches across Gujarat 🤺💙 I\'m an AI assistant — for official decisions, the AFAGS office has the final word.',hi:'मुझे <b>AFAGS</b> के लिए बनाया गया है ताकि पूरे गुजरात के फेंसर, माता-पिता और कोच की मदद कर सकूँ 🤺💙',gu:'મને <b>AFAGS</b> માટે બનાવ્યો છે જેથી આખા ગુજરાતના ફેન્સર, વાલીઓ અને કોચને મદદ કરી શકું 🤺💙',hl:'Mujhe <b>AFAGS</b> ke liye banaya gaya hai — Gujarat ke fencers, parents aur coaches ki help ke liye 🤺💙'}),c:chipsFor(L)};
  if(/\b(time|date|day today|aaj kya|aaje shu|aaj ki date|today'?s date)\b|तारीख|આજે/i.test(q)&&/\b(time|date|today|aaj|aaje|day)\b|तारीख|આજે/i.test(q)&&q.length<45){const d=new Date();return {mood:'cool',a:`🕒 ${d.toLocaleString(L==='hi'||L==='hl'?'hi-IN':L==='gu'||L==='gl'?'gu-IN':'en-IN',{weekday:'long',day:'numeric',month:'long',year:'numeric',hour:'numeric',minute:'2-digit'})}`,c:chipsFor(L)}}
  if(/\b(good night|gn|shubh ratri|sweet dreams)\b|शुभ रात्रि|શુભ રાત્રિ/i.test(q))return {mood:'caring',a:T(L,{en:'Good night! 🌙 Rest well — recovery is training too. 😴🤺',hi:'शुभ रात्रि! 🌙 अच्छे से आराम करो — रिकवरी भी ट्रेनिंग है। 😴',gu:'શુભ રાત્રિ! 🌙 સારો આરામ કરો — રિકવરી પણ ટ્રેનિંગ છે. 😴',hl:'Good night! 🌙 Achhe se aaram karo — recovery bhi training hai 😴'}),c:[]};
  return null}
const chipsFor=L=>T(L,{en:['How do I register?','Next event','Tell me a joke 😂','Quiz 🧠'],hi:['पंजीकरण कैसे?','अगली प्रतियोगिता','जोक सुनाओ 😂','Quiz 🧠'],gu:['નોંધણી કેવી રીતે?','આગામી સ્પર્ધા','જોક કહો 😂','Quiz 🧠'],hl:['Registration kaise kare?','Next event kab hai?','Ek joke sunao 😂','Quiz 🧠'],gl:['Nondhani kevi rite?','Aagami spardha','Joke kaho 😂','Quiz 🧠']});
function startQuiz(L){const order=QUIZ.map((_,i)=>i).sort(()=>Math.random()-.5).slice(0,5);ST.quiz={order,i:0,s:0,L};return {mood:'excited',a:T(L,{en:'🧠 <b>Fencing Quiz</b> — 5 questions. Ready? En garde!',hi:'🧠 <b>फेंसिंग क्विज़</b> — 5 सवाल। तैयार? En garde!',gu:'🧠 <b>ફેન્સિંગ ક્વિઝ</b> — 5 પ્રશ્નો. તૈયાર? En garde!',hl:'🧠 <b>Fencing Quiz</b> — 5 sawaal. Ready? En garde!',gl:'🧠 <b>Fencing Quiz</b> — 5 prashno. Taiyar? En garde!'})+quizQ(),c:[]}}
function quizQ(){const Q=ST.quiz,q=QUIZ[Q.order[Q.i]];return `<div class="jg-q"><small>Q${Q.i+1}/5</small><p>${q[0]}</p><div>${q[1].map((o,k)=>`<button type="button" class="jg-opt" data-qa="${k}">${esc(o)}</button>`).join('')}</div></div>`}
const gameButtons=()=>`<div class="jg-game">${Object.entries(GAME).map(([k,[i,l]])=>`<button type="button" class="jg-opt" data-gm="${k}"><span>${i}</span>${l}</button>`).join('')}</div><div class="jg-score">You <b>${ST.score[0]}</b> : <b>${ST.score[1]}</b> Jig</div>`;

/* ---- safe mini-markdown for AI replies ---- */
function md(t){const lines=esc(t).split(/\n/);let out='',inL=false;
  const inline=s=>s.replace(/\*\*(.+?)\*\*/g,'<b>$1</b>').replace(/(^|[\s(])\*([^*\n]+)\*(?=[\s).,!?]|$)/g,'$1<i>$2</i>').replace(/\[([^\]]{1,60})\]\((#\/[a-z0-9/_-]*)\)/gi,(_,l,h)=>`<a href="${h}" class="pc-l">${l} ›</a>`).replace(/\[([^\]]{1,60})\]\((https:\/\/(?:www\.)?fencingindia\.org[^)\s]*)\)/gi,(_,l,h)=>`<a href="${h}" target="_blank" rel="noopener noreferrer" class="pc-l">${l} ↗</a>`);
  for(const ln of lines){const m=/^\s*(?:[-•*]|\d+[.)])\s+(.*)$/.exec(ln);if(m){if(!inL){out+='<ul>';inL=true}out+=`<li>${inline(m[1])}</li>`}else{if(inL){out+='</ul>';inL=false}out+=ln.trim()?inline(ln)+'<br>':''}}
  if(inL)out+='</ul>';return out.replace(/(<br>)+$/,'')}
const plain=h=>{const d=document.createElement('div');d.innerHTML=h;d.querySelectorAll('.pc-l,.jg-q,.jg-game,.jg-score,.jg-links').forEach(x=>x.remove());return d.textContent.replace(/\s+/g,' ').trim()};

