function setChips(c){chips.innerHTML=(c||[]).map(x=>`<button type="button">${esc(x)}</button>`).join('')}
function confetti(){if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;const w=document.createElement('div');w.className='jg-conf';w.innerHTML=Array.from({length:28},(_,i)=>`<i style="--x:${Math.random()*100}%;--d:${(Math.random()*.6).toFixed(2)}s;--r:${Math.floor(Math.random()*360)}deg;--c:${['#f47b20','#2c7bff','#22c55e','#facc15','#ec4899','#fff'][i%6]}"></i>`).join('');panel.appendChild(w);setTimeout(()=>w.remove(),2200)}
function say(text,L){if(!('speechSynthesis' in window)||!text)return;try{speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text.replace(/[\u{1F300}-\u{1FAFF}\u{2600}-\u{27BF}›↗]/gu,'').slice(0,600));u.lang=SPEECH[L]||'en-IN';const v=speechSynthesis.getVoices().find(v=>v.lang===u.lang)||speechSynthesis.getVoices().find(v=>v.lang&&v.lang.startsWith(u.lang.slice(0,2)));if(v)u.voice=v;u.rate=1.02;u.pitch=1.08;speechSynthesis.speak(u)}catch(e){}}
const MAP={'Contact AFAGS':'contact','Track my application':'track status','Find a club':'find a club near me','Next event':'next event','Documents needed':'documents','Fencer registration':'fencer registration','Coach registration':'coach registration','Referee registration':'referee registration','Club registration':'club registration','District unit registration':'district unit registration'};
